    "title": {
      "type": "Text",
      "props": {
        "text": "Utah National Parks Family Adventure",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Embark on a memorable 7-day family road trip through Utah's iconic National Parks, starting and ending in Salt Lake City. This itinerary focuses on moderate hikes and breathtaking scenic viewpoints, perfectly suited for families with children aged 10 and 12, while navigating the summer heat of July 2024."
      },
      "children": []
    },
    "context_card": {
      "type": "Card",
      "props": {},
      "children": [
        "context_heading",
        "context_table"
      ]
    },
    "context_heading": {
      "type": "Text",
      "props": {
        "text": "Context for Your Trip",
        "variant": "h3"
      },
      "children": []
    },
    "context_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "details",
            "label": "Details"
          }
        ],
        "rows": [
          {
            "category": "Travel Season",
            "details": "July in Southern Utah is very hot. Plan for early morning activities, carry plenty of water (at least 1 gallon per person per day for hiking), wear wide-brimmed hats, sunscreen, and light clothing."
          },
          {
            "category": "Accommodation",
            "details": "This itinerary assumes overnight stays in Springdale (near Zion), Bryce Canyon City (near Bryce), and Moab (near Arches). Book lodging well in advance."
          },
          {
            "category": "Transportation",
            "details": "A rental car is essential for this road trip."
          },
          {
            "category": "National Park Entry",
            "details": "Consider purchasing an \"America the Beautiful\" annual pass if you plan to visit multiple national parks, as individual park entry fees can add up."
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "itinerary_heading": {
      "type": "Text",
      "props": {
        "text": "7-Day Road Trip Itinerary: Salt Lake City to Utah's Mighty 5",
        "variant": "h2"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_title_stack",
        "day1_details_table"
      ]
    },
    "day1_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
