      ]
    },
    "day1_title": {
      "type": "Text",
      "props": {
        "text": "Day 1: Salt Lake City to Springdale (Zion National Park)",
        "variant": "h3"
      },
      "children": []
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/car-front.svg"
      },
      "children": []
    },
    "day1_details_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          }
        ],
        "rows": [
          {
            "time": "Morning",
            "activity": "Begin your drive south from Salt Lake City towards Springdale, the gateway town to Zion National Park (approx. 4.5-5 hours drive)."
          },
          {
            "time": "Afternoon",
            "activity": "Check into your accommodation in Springdale. Relax by the pool or explore the charming town."
          },
          {
            "time": "Food",
            "activity": "Enjoy a casual dinner at Oscar's Cafe in Springdale, known for its Southwestern cuisine and outdoor seating."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time"
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_title_stack",
        "day2_details_table"
      ]
    },
    "day2_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day2_title",
        "day2_icon"
      ]
