    "day2_title": {
      "type": "Text",
      "props": {
        "text": "Day 2: Zion National Park Exploration",
        "variant": "h3"
      },
      "children": []
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg"
      },
      "children": []
