    "day2_details_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          }
        ],
        "rows": [
          {
            "time": "Morning",
            "activity": "Take the park shuttle to the Emerald Pools Trail. This moderate hike offers lush greenery and waterfalls, with options for lower, middle, and upper pools (approx. 2-3 hours)."
          },
          {
            "time": "Afternoon",
            "activity": "Walk the scenic Riverside Walk (easy, paved, 2.2 miles round trip), leading to the entrance of The Narrows. Kids will love wading in the Virgin River at the end of the paved trail."
          },
          {
            "time": "Food",
            "activity": "Pack a picnic lunch to enjoy within the park. For dinner, try Zion Canyon Brew Pub for family-friendly food and local brews."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time"
      },
      "children": []
    },
