          },
          {
            "key": "activity",
            "label": "Activity"
          }
        ],
        "rows": [
          {
            "time": "Morning",
            "activity": "Enjoy an early morning bike ride or walk along the Pa'rus Trail (easy, paved) along the Virgin River, offering stunning canyon views. Alternatively, for a slightly more challenging option, hike the Canyon Overlook Trail (moderate, 1 mile round trip) for panoramic views."
          },
          {
            "time": "Afternoon",
            "activity": "Drive from Zion to Bryce Canyon National Park (approx. 1.5-2 hours). Settle into your lodging in Bryce Canyon City."
          },
          {
            "time": "Food",
            "activity": "Have dinner at Rubys Inn Cowboy's Buffet & Steak Room, offering a wide selection for all tastes."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
