      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          }
        ],
        "rows": [
          {
            "time": "Morning",
            "activity": "Hike the iconic Navajo Loop and Queen's Garden Trail (moderate, 3.1 miles loop). This trail descends into the amphitheater, surrounded by towering hoodoos. Start early to beat the heat."
          },
          {
            "time": "Afternoon",
            "activity": "Explore the scenic viewpoints along the rim, such as Inspiration Point, Bryce Point, and Sunset Point, offering different perspectives of the unique geological formations."
          },
          {
            "time": "Food",
            "activity": "Grab a casual lunch at the Bryce Canyon Lodge Dining Room or enjoy a burger at Foster's Family Steakhouse."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time"
      },
      "children": []
