        "rows": [
          {
            "time": "Morning",
            "activity": "Hike to the iconic Delicate Arch (moderate, 3 miles round trip). This is a must-see, but start early to avoid the midday sun."
          },
          {
            "time": "Afternoon",
            "activity": "Explore the Windows Section (easy, 1-mile loop to Turret Arch, North Window, and South Window) and the Landscape Arch Trail (easy, 1.6 miles round trip) in the Devil's Garden area."
          },
          {
            "time": "Food",
            "activity": "Enjoy pizza at Moab Brewery or Antica Forma, both popular family spots."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
