        "rows": [
          {
            "time": "Morning",
            "activity": "If time allows before your drive, visit Dead Horse Point State Park (a short drive from Moab) for stunning canyon views that rival the Grand Canyon. Alternatively, enjoy a leisurely breakfast in Moab."
          },
          {
            "time": "Afternoon",
            "activity": "Begin your drive back to Salt Lake City (approx. 3.5-4 hours), reflecting on the incredible natural beauty of Utah's National Parks."
          },
          {
            "time": "Food",
            "activity": "Stop for a late lunch or early dinner on your way back, or enjoy a final meal in Salt Lake City."
          }
        ],
        "domain": "schedule",
